{"implementation":"def solve(case):
    payload = case.get('payload', case)
    nodes = list(payload.get('nodes', []))
    core = dict(payload.get('core_distance', {}))
    distances = list(payload.get('distances', []))

    order = {node: i for i, node in enumerate(nodes)}

    edges = []
    for item in distances:
        a, b, d = item[0], item[1], item[2]
        w = max(float(d), float(core[a]), float(core[b]))
        edges.append((w, order.get(a, 0), order.get(b, 0), a, b, float(d)))

    edges.sort(key=lambda x: (x[0], x[1], x[2], x[3], x[4]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1
        return True

    mst = []
    total = 0.0
    for w, _, _, a, b, original in edges:
        if union(a, b):
            edge = {
                'u': a,
                'v': b,
                'distance': original,
                'mutual_reachability': w,
                'lambda': (1.0 / w) if w != 0 else None,
            }
            mst.append(edge)
            total += w
            if len(mst) == max(0, len(nodes) - 1):
                break

    return {
        'edges': [
            {
                'u': a,
                'v': b,
                'distance': original,
                'mutual_reachability': w,
                'lambda': (1.0 / w) if w != 0 else None,
            }
            for w, _, _, a, b, original in edges
        ],
        'mst': mst,
        'total_weight': total,
    }
